import{_ as t,o as r,c as a,a2 as i}from"./chunks/framework.il0noOp3.js";const f=JSON.parse('{"title":"WAF — the five pillar design-review checklists, enumerated","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/waf-pillar-checklists.md","filePath":"frameworks/waf-pillar-checklists.md"}'),o={name:"frameworks/waf-pillar-checklists.md"};function s(d,e,c,n,l,h){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="waf-—-the-five-pillar-design-review-checklists-enumerated" tabindex="-1">WAF — the five pillar design-review checklists, enumerated <a class="header-anchor" href="#waf-—-the-five-pillar-design-review-checklists-enumerated" aria-label="Permalink to &quot;WAF — the five pillar design-review checklists, enumerated&quot;">​</a></h1><blockquote><p><strong>Source:</strong> <a href="https://learn.microsoft.com/en-us/azure/well-architected/reliability/checklist" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/azure/well-architected/reliability/checklist</a> · <a href="https://learn.microsoft.com/en-us/azure/well-architected/security/checklist" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/azure/well-architected/security/checklist</a> · <a href="https://learn.microsoft.com/en-us/azure/well-architected/cost-optimization/checklist" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/azure/well-architected/cost-optimization/checklist</a> · <a href="https://learn.microsoft.com/en-us/azure/well-architected/operational-excellence/checklist" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/azure/well-architected/operational-excellence/checklist</a> · <a href="https://learn.microsoft.com/en-us/azure/well-architected/performance-efficiency/checklist" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/azure/well-architected/performance-efficiency/checklist</a><strong>Framework version:</strong> Microsoft does not version the WAF checklists; this enumeration uses the extraction date, 2026-08-01, as the version. <strong>Extracted:</strong> 2026-08-01 <strong>Verification method:</strong> Each of the five pillar checklist pages was fetched directly via <code>microsoft_docs_fetch</code> (Microsoft Learn MCP server) and every checklist row transcribed. Nothing in this file was taken on trust from a prior audit; the 59-item total is a direct re-count, not a carried-forward figure.</p></blockquote><p><strong>Enumerated 2026-08-01.</strong> This is the source-framework enumeration required by AB#6745 (Epic AB#6454). It exists so rule files under <code>src/assess/rules/waf.*.yaml</code> cite a real, checkable item number instead of a pillar name and a vibe. The audit&#39;s DQ12 explains why this matters: <em>&quot;Writing rules against a framework you have not enumerated is how <code>waf.storage.yaml</code> happened&quot;</em> — a rule file scoring a WAF pillar that does not exist (storage is a WAF <em>service guide</em>, not a pillar; see <code>pmo/audits/AZURE-SCOUT-AUDIT.md</code> §8).</p><h2 id="what-this-is" tabindex="-1">What this is <a class="header-anchor" href="#what-this-is" aria-label="Permalink to &quot;What this is&quot;">​</a></h2><p>The Azure Well-Architected Framework publishes exactly <strong>five pillars</strong> — Reliability, Security, Cost Optimization, Operational Excellence, Performance Efficiency — confirmed on <a href="https://learn.microsoft.com/en-us/azure/well-architected/what-is-well-architected-framework" target="_blank" rel="noreferrer">What is the Well-Architected Framework?</a>. Each pillar ships one <strong>design review checklist</strong> page. Every checklist item on that page has a Microsoft-published, stable code (<code>RE:01</code>, <code>SE:04</code>, and so on) — unlike CAF&#39;s landing-zone recommendations, which have no Microsoft item numbers at all (see <code>docs/frameworks/caf-landing-zone-design-areas.md</code>). Scout&#39;s <code>WAF-&lt;PILLAR&gt;-&lt;NN&gt;</code> identifiers below are a direct, 1:1 restatement of Microsoft&#39;s own codes, using the pillar abbreviation (<code>RE</code>/<code>SE</code>/<code>CO</code>/<code>OE</code>/<code>PE</code>) already in use by <code>src/assess/rules/waf.*.yaml</code> (e.g. <code>WAF-SE-01</code> in <code>waf.security.yaml</code>, <code>WAF-RE-05</code> in <code>waf.reliability.yaml</code>).</p><h2 id="verification-method" tabindex="-1">Verification method <a class="header-anchor" href="#verification-method" aria-label="Permalink to &quot;Verification method&quot;">​</a></h2><p>Each pillar&#39;s checklist page was fetched directly on 2026-08-01 via <code>microsoft_docs_fetch</code> (Microsoft Learn MCP server), not taken on trust from the prior audit. The audit&#39;s §8 Table 1 stated 59 items total across the five pillars; that figure is <strong>confirmed exactly</strong> by this re-fetch — 10 + 12 + 14 + 11 + 12 = 59. Item text below is Microsoft&#39;s own checklist wording, transcribed from the fetched page (the lead sentence of each checklist row; the fuller elaboration sentence that follows each item on Microsoft&#39;s page is omitted here for table width, and readers needing the full wording should follow the <code>Code</code> link to the live page).</p><table tabindex="0"><thead><tr><th>Pillar</th><th>Source URL</th><th>Items fetched</th></tr></thead><tbody><tr><td>Reliability</td><td><a href="https://learn.microsoft.com/en-us/azure/well-architected/reliability/checklist" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/azure/well-architected/reliability/checklist</a></td><td>10</td></tr><tr><td>Security</td><td><a href="https://learn.microsoft.com/en-us/azure/well-architected/security/checklist" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/azure/well-architected/security/checklist</a></td><td>12</td></tr><tr><td>Cost Optimization</td><td><a href="https://learn.microsoft.com/en-us/azure/well-architected/cost-optimization/checklist" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/azure/well-architected/cost-optimization/checklist</a></td><td>14</td></tr><tr><td>Operational Excellence</td><td><a href="https://learn.microsoft.com/en-us/azure/well-architected/operational-excellence/checklist" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/azure/well-architected/operational-excellence/checklist</a></td><td>11</td></tr><tr><td>Performance Efficiency</td><td><a href="https://learn.microsoft.com/en-us/azure/well-architected/performance-efficiency/checklist" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/azure/well-architected/performance-efficiency/checklist</a></td><td>12</td></tr><tr><td><strong>Total</strong></td><td>—</td><td><strong>59</strong></td></tr></tbody></table><p><strong>Framework version:</strong> the current (2026-08-01) Azure Well-Architected Framework checklist content. Microsoft does not date-stamp or version-number this content; &quot;current&quot; means &quot;as published on the URL above on the extraction date.&quot;</p><h2 id="reliability-—-waf-re-10-items" tabindex="-1">Reliability — <code>WAF-RE-*</code> (10 items) <a class="header-anchor" href="#reliability-—-waf-re-10-items" aria-label="Permalink to &quot;Reliability — `WAF-RE-*` (10 items)&quot;">​</a></h2><p>Source: <a href="https://learn.microsoft.com/en-us/azure/well-architected/reliability/checklist" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/azure/well-architected/reliability/checklist</a></p><table tabindex="0"><thead><tr><th>#</th><th>Item</th></tr></thead><tbody><tr><td>WAF-RE-01</td><td>Focus your workload design on simplicity and efficiency.</td></tr><tr><td>WAF-RE-02</td><td>Identify and rate user and system flows, using a criticality scale based on business requirements.</td></tr><tr><td>WAF-RE-03</td><td>Use failure mode analysis (FMA) to identify potential failures in your workload.</td></tr><tr><td>WAF-RE-04</td><td>Define reliability and recovery targets for your workload.</td></tr><tr><td>WAF-RE-05</td><td>Add redundancy at different levels, especially for critical flows, to help meet reliability targets.</td></tr><tr><td>WAF-RE-06</td><td>Implement a timely and reliable scaling strategy at the application, data, and infrastructure levels.</td></tr><tr><td>WAF-RE-07</td><td>Strengthen resiliency by implementing self-preservation and self-healing measures.</td></tr><tr><td>WAF-RE-08</td><td>Test for resiliency and availability scenarios by applying the principles of chaos engineering.</td></tr><tr><td>WAF-RE-09</td><td>Implement structured, tested, and documented disaster recovery (DR) plans that align with recovery targets.</td></tr><tr><td>WAF-RE-10</td><td>Continuously measure and track system health using uptime and reliability indicators.</td></tr></tbody></table><h2 id="security-—-waf-se-12-items" tabindex="-1">Security — <code>WAF-SE-*</code> (12 items) <a class="header-anchor" href="#security-—-waf-se-12-items" aria-label="Permalink to &quot;Security — `WAF-SE-*` (12 items)&quot;">​</a></h2><p>Source: <a href="https://learn.microsoft.com/en-us/azure/well-architected/security/checklist" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/azure/well-architected/security/checklist</a></p><table tabindex="0"><thead><tr><th>#</th><th>Item</th></tr></thead><tbody><tr><td>WAF-SE-01</td><td>Establish a security baseline aligned to compliance requirements, industry standards, and platform recommendations.</td></tr><tr><td>WAF-SE-02</td><td>Align the secure development lifecycle (SDL) throughout the software development lifecycle.</td></tr><tr><td>WAF-SE-03</td><td>Classify and consistently apply sensitivity and information-type labels on all workload data.</td></tr><tr><td>WAF-SE-04</td><td>Create intentional segmentation and perimeters in your architecture design and platform footprint.</td></tr><tr><td>WAF-SE-05</td><td>Implement strict, conditional, and auditable identity and access management (IAM) across all workload users, team members, and system components.</td></tr><tr><td>WAF-SE-06</td><td>Isolate, filter, and control network traffic across both ingress and egress flows.</td></tr><tr><td>WAF-SE-07</td><td>Encrypt data by using modern, industry-standard methods.</td></tr><tr><td>WAF-SE-08</td><td>Harden all workload components by reducing extraneous surface area and tightening configurations.</td></tr><tr><td>WAF-SE-09</td><td>Protect application secrets by hardening their storage, restricting access, and rotating regularly.</td></tr><tr><td>WAF-SE-10</td><td>Implement a holistic monitoring strategy that relies on modern threat detection mechanisms.</td></tr><tr><td>WAF-SE-11</td><td>Establish a comprehensive testing regimen combining approaches to prevent, validate, and detect threats.</td></tr><tr><td>WAF-SE-12</td><td>Define and test effective incident response procedures.</td></tr></tbody></table><p>Note: <code>waf.security.yaml</code>&#39;s <code>WAF-SE-01</code>–<code>WAF-SE-07</code> are Scout&#39;s own rule IDs, assigned before this enumeration existed, and do <strong>not</strong> currently map one-to-one to the Microsoft codes above (Scout&#39;s <code>WAF-SE-03</code> is a SQL public-access rule, unrelated to Microsoft&#39;s <code>SE:03</code> data classification item). This is a naming collision the rule file inherited, not a citation — see &quot;What this means for the rule file&quot; below.</p><h2 id="cost-optimization-—-waf-co-14-items" tabindex="-1">Cost Optimization — <code>WAF-CO-*</code> (14 items) <a class="header-anchor" href="#cost-optimization-—-waf-co-14-items" aria-label="Permalink to &quot;Cost Optimization — `WAF-CO-*` (14 items)&quot;">​</a></h2><p>Source: <a href="https://learn.microsoft.com/en-us/azure/well-architected/cost-optimization/checklist" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/azure/well-architected/cost-optimization/checklist</a></p><table tabindex="0"><thead><tr><th>#</th><th>Item</th></tr></thead><tbody><tr><td>WAF-CO-01</td><td>Create a culture of financial responsibility.</td></tr><tr><td>WAF-CO-02</td><td>Create and maintain a cost model estimating initial cost, run rates, and ongoing costs.</td></tr><tr><td>WAF-CO-03</td><td>Collect and review cost data, including incurred, prepaid, trends, and forecasts.</td></tr><tr><td>WAF-CO-04</td><td>Set spending guardrails — release gates, governance policies, resource limits, access controls.</td></tr><tr><td>WAF-CO-05</td><td>Get the best rates from providers — regional pricing, tiers, commitment models, license portability.</td></tr><tr><td>WAF-CO-06</td><td>Align usage to billing increments (meters).</td></tr><tr><td>WAF-CO-07</td><td>Optimize component costs — remove or optimize legacy, unneeded, and underutilized components.</td></tr><tr><td>WAF-CO-08</td><td>Optimize environment costs — align spend to preproduction, production, operations, and DR needs.</td></tr><tr><td>WAF-CO-09</td><td>Optimize flow costs — align cost of each flow with flow priority.</td></tr><tr><td>WAF-CO-10</td><td>Optimize data costs — tiering, retention, volume, replication, backups, file formats.</td></tr><tr><td>WAF-CO-11</td><td>Optimize code costs — evaluate and modify code to meet requirements with fewer/cheaper resources.</td></tr><tr><td>WAF-CO-12</td><td>Optimize scaling costs — evaluate alternative scaling configurations against the cost model.</td></tr><tr><td>WAF-CO-13</td><td>Optimize personnel time on tasks aligned with task priority.</td></tr><tr><td>WAF-CO-14</td><td>Consolidate resources and responsibility to increase density.</td></tr></tbody></table><h2 id="operational-excellence-—-waf-oe-11-items" tabindex="-1">Operational Excellence — <code>WAF-OE-*</code> (11 items) <a class="header-anchor" href="#operational-excellence-—-waf-oe-11-items" aria-label="Permalink to &quot;Operational Excellence — `WAF-OE-*` (11 items)&quot;">​</a></h2><p>Source: <a href="https://learn.microsoft.com/en-us/azure/well-architected/operational-excellence/checklist" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/azure/well-architected/operational-excellence/checklist</a></p><table tabindex="0"><thead><tr><th>#</th><th>Item</th></tr></thead><tbody><tr><td>WAF-OE-01</td><td>Define your standard practices to develop and operate your workload.</td></tr><tr><td>WAF-OE-02</td><td>Use standardization to make routine, ad-hoc, and emergency operations consistent and predictable.</td></tr><tr><td>WAF-OE-03</td><td>Formalize processes across the full software development lifecycle, from ideation to delivery.</td></tr><tr><td>WAF-OE-04</td><td>Enhance software development and QA by implementing industry-standard practices.</td></tr><tr><td>WAF-OE-05</td><td>Use a standardized infrastructure as code (IaC) approach to prepare resources and configurations.</td></tr><tr><td>WAF-OE-06</td><td>Build a workload supply chain that drives changes through predictable, automated pipelines.</td></tr><tr><td>WAF-OE-07</td><td>Design a monitoring stack that captures operational telemetry, metrics, and logs.</td></tr><tr><td>WAF-OE-08</td><td>Establish a clear, structured incident management process.</td></tr><tr><td>WAF-OE-09</td><td>Enhance workload quality by adopting testing practices aligned with business objectives.</td></tr><tr><td>WAF-OE-10</td><td>Design automation to be reliable, secure, and maintainable across the workload lifecycle.</td></tr><tr><td>WAF-OE-11</td><td>Clearly define your workload&#39;s safe deployment practices.</td></tr></tbody></table><h2 id="performance-efficiency-—-waf-pe-12-items" tabindex="-1">Performance Efficiency — <code>WAF-PE-*</code> (12 items) <a class="header-anchor" href="#performance-efficiency-—-waf-pe-12-items" aria-label="Permalink to &quot;Performance Efficiency — `WAF-PE-*` (12 items)&quot;">​</a></h2><p>Source: <a href="https://learn.microsoft.com/en-us/azure/well-architected/performance-efficiency/checklist" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/azure/well-architected/performance-efficiency/checklist</a></p><table tabindex="0"><thead><tr><th>#</th><th>Item</th></tr></thead><tbody><tr><td>WAF-PE-01</td><td>Define performance targets, as numerical values tied to workload requirements.</td></tr><tr><td>WAF-PE-02</td><td>Conduct capacity planning ahead of predicted usage-pattern changes.</td></tr><tr><td>WAF-PE-03</td><td>Select the right services, infrastructure, and tiers to reach performance targets.</td></tr><tr><td>WAF-PE-04</td><td>Establish consistent performance measurement so behavior can be analyzed over time.</td></tr><tr><td>WAF-PE-05</td><td>Optimize scaling and partitioning — the scale-unit design is the basis of the strategy.</td></tr><tr><td>WAF-PE-06</td><td>Regularly test performance in a production-like environment.</td></tr><tr><td>WAF-PE-07</td><td>Optimize code and infrastructure — performant code that offloads responsibility to the platform.</td></tr><tr><td>WAF-PE-08</td><td>Optimize data usage — data stores, partitions, and indexes for intended and actual use.</td></tr><tr><td>WAF-PE-09</td><td>Prioritize the performance of critical flows.</td></tr><tr><td>WAF-PE-10</td><td>Optimize operational tasks that affect workload performance (patching, scans, backups, reindexing).</td></tr><tr><td>WAF-PE-11</td><td>Respond to live performance issues with clear communication and responsibility lines.</td></tr><tr><td>WAF-PE-12</td><td>Continuously optimize performance, focusing on components with deteriorating performance over time.</td></tr></tbody></table><h2 id="what-this-means-for-the-rule-file" tabindex="-1">What this means for the rule file <a class="header-anchor" href="#what-this-means-for-the-rule-file" aria-label="Permalink to &quot;What this means for the rule file&quot;">​</a></h2><p><code>src/assess/rules/waf.storage.yaml</code> scores a sixth &quot;WAF pillar&quot; — storage — that does not exist in this enumeration. Per the audit&#39;s §8 recommendation, its five rules should be redistributed into the pillar files they actually belong to (durability/replication → <code>WAF-RE-05</code>, encryption/public-access → <code>WAF-SE-06</code>/<code>WAF-SE-07</code>, tiering/lifecycle → <code>WAF-CO-10</code>) and the file deleted, or the whole thing re-modeled as a WAF <em>service guide</em> axis (<code>svc.storage.yaml</code>) that is explicitly not a pillar score.</p><p>The existing <code>waf.*.yaml</code> rule IDs (<code>WAF-SE-01</code> through <code>WAF-SE-07</code>, etc.) predate this enumeration and were assigned by rule area, not by Microsoft checklist code — they are <strong>not</strong> citations of the items above. Any rule written or renumbered after this file exists should cite the Microsoft code directly (e.g. a new segmentation rule cites <code>WAF-SE-04</code>), so <code>manual: true</code> rules can state exactly which unscorable checklist item they stand in for, the way <code>smart-question-set.md</code>&#39;s items map to named CAF pages.</p>',28)])])}const u=t(o,[["render",s]]);export{f as __pageData,u as default};
